REPORT = "# FS-2.4.2 — Module Boundary Non-Regression Gate\n\n**Branch:** `feat/repository-baseline-consolidation`\n**Phase:** `FS-2.4 — Dependency and module boundary audit`\n**Golden module:** Partner\n\n## Purpose\n\nFS-2.4.2 turns the reviewed FS-2.4.1 business-module dependency baseline into\na permanent non-regression gate.\n\nThe gate is intentionally conservative:\n\n```text\nexisting reviewed public seam\n        => allowed\n\nnew business-to-business seam\n        => fail until explicitly reviewed\n```\n\nIt does not rename packages or refactor functional code.\n\n## Current reviewed business edges\n\n```text\nPartner        -> Security\nCustomer       -> Security\nPayment        -> Security\nAdministration -> Security\n```\n\nNo other business-to-business edge is currently approved.\n\n## Explicit Security public surface\n\nAccepted authentication-context contracts:\n\n```text\ncom.sixpay.security.authentication.CurrentUserProvider\ncom.sixpay.security.authentication.AuthenticatedUser\ncom.sixpay.security.authentication.SixpayPrincipal\n```\n\nAccepted authorization contracts:\n\n```text\ncom.sixpay.security.authorization.*\n```\n\nAccepted input-port conventions:\n\n```text\ncom.sixpay.security.application.port.in.*\ncom.sixpay.security.application.port.input.*\n```\n\nBoth historical naming conventions are treated as equivalent.\n\nAccepted application response contracts:\n\n```text\ncom.sixpay.security.application.model.*\n```\n\nConcrete Security internals remain private, including\n`SecurityContextCurrentUserProvider`, JWT, infrastructure and configuration.\n\n## Forbidden cross-module surfaces\n\nA business module must never import another business module's:\n\n```text\n*.infrastructure.*\n*.domain.repository.*\n*.entity.*\n*JpaEntity*\n*.application.port.out.*\n*.application.port.output.*\n*.configuration.*\n*.config.*\n```\n\n## Exact-edge policy\n\nA future edge such as Payment -> Customer or Accounting -> Payment fails even\nif the imported class looks harmless. It must first be explicitly reviewed.\n\n## Cycle and Maven policy\n\nThe gate rejects Java cycles and Maven business-module cycles.\n\nEvery business Maven compile dependency must correspond to a real reviewed\nproduction Java edge, and every production Java business edge must have its\nmatching Maven dependency.\n\nThis prevents unused coupling from returning.\n\n## Regression policy\n\nFS-2.4 remains classification-first:\n\n```text\ndetect\n  -> inspect\n  -> prove violation\n  -> minimal targeted correction\n  -> module tests\n  -> consumer tests\n  -> full reactor verification\n```\n\nExisting functional behavior is the protected baseline.\n"
JAVA = 'package com.sixpay.bootstrap.architecture;\n\nimport org.junit.jupiter.api.Test;\n\nimport javax.xml.parsers.DocumentBuilderFactory;\n\nimport java.io.IOException;\nimport java.nio.file.Files;\nimport java.nio.file.Path;\nimport java.util.ArrayDeque;\nimport java.util.ArrayList;\nimport java.util.Deque;\nimport java.util.HashSet;\nimport java.util.LinkedHashMap;\nimport java.util.LinkedHashSet;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Set;\nimport java.util.regex.Matcher;\nimport java.util.regex.Pattern;\n\nimport static org.junit.jupiter.api.Assertions.assertTrue;\n\nclass BusinessModuleBoundaryArchitectureTest {\n\n    private static final Path BACKEND_ROOT =\n            Path.of("..");\n\n    private static final List<String> BUSINESS_MODULES =\n            List.of(\n                    "partner",\n                    "customer",\n                    "payment",\n                    "accounting",\n                    "reporting",\n                    "notification",\n                    "security",\n                    "administration"\n            );\n\n    private static final Pattern IMPORT_PATTERN =\n            Pattern.compile(\n                    "^\\\\s*import\\\\s+(?:static\\\\s+)?"\n                            + "(com\\\\.sixpay\\\\.[A-Za-z0-9_.$*]+)"\n                            + "\\\\s*;",\n                    Pattern.MULTILINE\n            );\n\n    private static final Set<ModuleEdge> APPROVED_EDGES =\n            Set.of(\n                    new ModuleEdge("partner", "security"),\n                    new ModuleEdge("customer", "security"),\n                    new ModuleEdge("payment", "security"),\n                    new ModuleEdge("administration", "security")\n            );\n\n    private static final Set<String>\n            EXACT_PUBLIC_SECURITY_CONTRACTS =\n            Set.of(\n                    "com.sixpay.security.authentication.CurrentUserProvider",\n                    "com.sixpay.security.authentication.AuthenticatedUser",\n                    "com.sixpay.security.authentication.SixpayPrincipal"\n            );\n\n    private static final List<String>\n            PUBLIC_SECURITY_PREFIXES =\n            List.of(\n                    "com.sixpay.security.authorization.",\n                    "com.sixpay.security.application.port.in.",\n                    "com.sixpay.security.application.port.input.",\n                    "com.sixpay.security.application.model."\n            );\n\n    @Test\n    void businessModulesImportOnlyReviewedPublicSurfaces()\n            throws Exception {\n\n        ScanResult scan = scanProductionJava();\n\n        assertTrue(\n                scan.violations().isEmpty(),\n                () -> "Business module boundary violations: "\n                        + scan.violations()\n        );\n\n        assertTrue(\n                APPROVED_EDGES.containsAll(scan.edges()),\n                () -> "Unreviewed business-to-business edges: "\n                        + difference(scan.edges(), APPROVED_EDGES)\n        );\n    }\n\n    @Test\n    void productionJavaBusinessGraphIsAcyclic()\n            throws Exception {\n\n        List<String> cycles =\n                findCycles(\n                        adjacency(\n                                scanProductionJava().edges()\n                        )\n                );\n\n        assertTrue(\n                cycles.isEmpty(),\n                () -> "Circular Java business dependencies: "\n                        + cycles\n        );\n    }\n\n    @Test\n    void mavenBusinessDependenciesMatchReviewedJavaEdges()\n            throws Exception {\n\n        Set<ModuleEdge> javaEdges =\n                scanProductionJava().edges();\n\n        Set<ModuleEdge> mavenEdges =\n                scanMavenBusinessDependencies();\n\n        assertTrue(\n                difference(mavenEdges, javaEdges).isEmpty(),\n                () -> "Unused Maven business dependencies: "\n                        + difference(mavenEdges, javaEdges)\n        );\n\n        assertTrue(\n                difference(javaEdges, mavenEdges).isEmpty(),\n                () -> "Production Java business edges without "\n                        + "matching Maven dependency: "\n                        + difference(javaEdges, mavenEdges)\n        );\n\n        assertTrue(\n                APPROVED_EDGES.containsAll(mavenEdges),\n                () -> "Unreviewed Maven business edges: "\n                        + difference(mavenEdges, APPROVED_EDGES)\n        );\n    }\n\n    @Test\n    void mavenBusinessDependencyGraphIsAcyclic()\n            throws Exception {\n\n        List<String> cycles =\n                findCycles(\n                        adjacency(\n                                scanMavenBusinessDependencies()\n                        )\n                );\n\n        assertTrue(\n                cycles.isEmpty(),\n                () -> "Circular Maven business dependencies: "\n                        + cycles\n        );\n    }\n\n    private ScanResult scanProductionJava()\n            throws IOException {\n\n        Set<ModuleEdge> edges =\n                new LinkedHashSet<>();\n\n        List<String> violations =\n                new ArrayList<>();\n\n        for (String source : BUSINESS_MODULES) {\n\n            Path javaRoot =\n                    BACKEND_ROOT.resolve(\n                            source + "/src/main/java"\n                    );\n\n            if (!Files.isDirectory(javaRoot)) {\n                continue;\n            }\n\n            try (var files = Files.walk(javaRoot)) {\n                for (Path javaFile :\n                        files.filter(Files::isRegularFile)\n                                .filter(path ->\n                                        path.toString()\n                                                .endsWith(".java")\n                                )\n                                .toList()) {\n\n                    String sourceText =\n                            Files.readString(javaFile);\n\n                    Matcher matcher =\n                            IMPORT_PATTERN.matcher(sourceText);\n\n                    while (matcher.find()) {\n                        String imported =\n                                matcher.group(1);\n\n                        String target =\n                                businessModuleOf(imported);\n\n                        if (target == null\n                                || target.equals(source)) {\n                            continue;\n                        }\n\n                        ModuleEdge edge =\n                                new ModuleEdge(\n                                        source,\n                                        target\n                                );\n\n                        edges.add(edge);\n\n                        String violation =\n                                validateImport(\n                                        edge,\n                                        imported\n                                );\n\n                        if (violation != null) {\n                            violations.add(\n                                    javaFile\n                                            + " imports "\n                                            + imported\n                                            + ": "\n                                            + violation\n                            );\n                        }\n                    }\n                }\n            }\n        }\n\n        return new ScanResult(\n                Set.copyOf(edges),\n                List.copyOf(violations)\n        );\n    }\n\n    private String validateImport(\n            ModuleEdge edge,\n            String imported\n    ) {\n\n        if (!APPROVED_EDGES.contains(edge)) {\n            return "business edge is not explicitly approved";\n        }\n\n        if (containsForbiddenSurface(imported)) {\n            return "implementation/internal surface is forbidden";\n        }\n\n        if ("security".equals(edge.target())) {\n            if (EXACT_PUBLIC_SECURITY_CONTRACTS.contains(imported)) {\n                return null;\n            }\n\n            for (String prefix : PUBLIC_SECURITY_PREFIXES) {\n                if (imported.startsWith(prefix)) {\n                    return null;\n                }\n            }\n\n            return "Security surface is not part of "\n                    + "the reviewed public contract";\n        }\n\n        return "edge has no explicit public-surface policy";\n    }\n\n    private boolean containsForbiddenSurface(\n            String imported\n    ) {\n\n        String lower =\n                imported.toLowerCase();\n\n        return lower.contains(".infrastructure.")\n                || lower.contains(".domain.repository.")\n                || lower.contains(".application.port.out.")\n                || lower.contains(".application.port.output.")\n                || lower.contains(".configuration.")\n                || lower.contains(".config.")\n                || lower.contains(".entity.")\n                || lower.contains("jpaentity")\n                || lower.startsWith("com.sixpay.security.jwt.")\n                || imported.equals(\n                "com.sixpay.security.authentication."\n                        + "SecurityContextCurrentUserProvider"\n        );\n    }\n\n    private Set<ModuleEdge>\n    scanMavenBusinessDependencies()\n            throws Exception {\n\n        Set<ModuleEdge> edges =\n                new LinkedHashSet<>();\n\n        var factory =\n                DocumentBuilderFactory.newInstance();\n\n        factory.setNamespaceAware(false);\n\n        for (String source : BUSINESS_MODULES) {\n\n            Path pom =\n                    BACKEND_ROOT.resolve(\n                            source + "/pom.xml"\n                    );\n\n            if (!Files.isRegularFile(pom)) {\n                continue;\n            }\n\n            var document =\n                    factory.newDocumentBuilder()\n                            .parse(pom.toFile());\n\n            var dependencies =\n                    document.getElementsByTagName(\n                            "dependency"\n                    );\n\n            for (int i = 0;\n                 i < dependencies.getLength();\n                 i++) {\n\n                var dependency =\n                        dependencies.item(i);\n\n                String groupId =\n                        childText(\n                                dependency,\n                                "groupId"\n                        );\n\n                String artifactId =\n                        childText(\n                                dependency,\n                                "artifactId"\n                        );\n\n                String scope =\n                        childText(\n                                dependency,\n                                "scope"\n                        );\n\n                if (!"com.sixpay".equals(groupId)) {\n                    continue;\n                }\n\n                if (!BUSINESS_MODULES.contains(artifactId)) {\n                    continue;\n                }\n\n                if (artifactId.equals(source)) {\n                    continue;\n                }\n\n                if ("test".equals(scope)) {\n                    continue;\n                }\n\n                edges.add(\n                        new ModuleEdge(\n                                source,\n                                artifactId\n                        )\n                );\n            }\n        }\n\n        return Set.copyOf(edges);\n    }\n\n    private String childText(\n            org.w3c.dom.Node parent,\n            String name\n    ) {\n\n        var children =\n                parent.getChildNodes();\n\n        for (int i = 0;\n             i < children.getLength();\n             i++) {\n\n            var child =\n                    children.item(i);\n\n            if (name.equals(child.getNodeName())) {\n                return child\n                        .getTextContent()\n                        .trim();\n            }\n        }\n\n        return "";\n    }\n\n    private String businessModuleOf(\n            String imported\n    ) {\n\n        String prefix =\n                "com.sixpay.";\n\n        if (!imported.startsWith(prefix)) {\n            return null;\n        }\n\n        String remainder =\n                imported.substring(prefix.length());\n\n        int separator =\n                remainder.indexOf(\'.\');\n\n        String candidate =\n                separator >= 0\n                        ? remainder.substring(0, separator)\n                        : remainder;\n\n        return BUSINESS_MODULES.contains(candidate)\n                ? candidate\n                : null;\n    }\n\n    private Map<String, Set<String>>\n    adjacency(\n            Set<ModuleEdge> edges\n    ) {\n\n        Map<String, Set<String>> graph =\n                new LinkedHashMap<>();\n\n        for (String module : BUSINESS_MODULES) {\n            graph.put(\n                    module,\n                    new LinkedHashSet<>()\n            );\n        }\n\n        for (ModuleEdge edge : edges) {\n            graph.get(edge.source())\n                    .add(edge.target());\n        }\n\n        return graph;\n    }\n\n    private List<String> findCycles(\n            Map<String, Set<String>> graph\n    ) {\n\n        List<String> cycles =\n                new ArrayList<>();\n\n        Set<String> visited =\n                new HashSet<>();\n\n        Set<String> active =\n                new HashSet<>();\n\n        Deque<String> path =\n                new ArrayDeque<>();\n\n        for (String module : BUSINESS_MODULES) {\n            detectCycle(\n                    module,\n                    graph,\n                    visited,\n                    active,\n                    path,\n                    cycles\n            );\n        }\n\n        return cycles;\n    }\n\n    private void detectCycle(\n            String current,\n            Map<String, Set<String>> graph,\n            Set<String> visited,\n            Set<String> active,\n            Deque<String> path,\n            List<String> cycles\n    ) {\n\n        if (active.contains(current)) {\n            List<String> cycle =\n                    new ArrayList<>();\n\n            boolean collect = false;\n\n            for (String node : path) {\n                if (node.equals(current)) {\n                    collect = true;\n                }\n\n                if (collect) {\n                    cycle.add(node);\n                }\n            }\n\n            cycle.add(current);\n\n            cycles.add(\n                    String.join(\n                            " -> ",\n                            cycle\n                    )\n            );\n\n            return;\n        }\n\n        if (!visited.add(current)) {\n            return;\n        }\n\n        active.add(current);\n        path.addLast(current);\n\n        for (String target :\n                graph.getOrDefault(\n                        current,\n                        Set.of()\n                )) {\n\n            detectCycle(\n                    target,\n                    graph,\n                    visited,\n                    active,\n                    path,\n                    cycles\n            );\n        }\n\n        path.removeLast();\n        active.remove(current);\n    }\n\n    private <T> Set<T> difference(\n            Set<T> left,\n            Set<T> right\n    ) {\n\n        Set<T> result =\n                new LinkedHashSet<>(left);\n\n        result.removeAll(right);\n\n        return result;\n    }\n\n    private record ModuleEdge(\n            String source,\n            String target\n    ) {\n    }\n\n    private record ScanResult(\n            Set<ModuleEdge> edges,\n            List<String> violations\n    ) {\n    }\n}\n'

def fail(message):
    print(f"ERROR: {message}")
    sys.exit(1)

def require(path):
    if not path.is_file():
        fail(f"Missing required file: {path}")
    return path.read_text(encoding="utf-8")

def main():
    engineering = require(ENGINEERING)

    if EXPECTED_BRANCH not in engineering:
        fail(
            "ENGINEERING_CONTEXT.md does not declare "
            + EXPECTED_BRANCH
        )

    fs_241 = (
        ROOT
        / "documentation/architecture/module-boundaries/"
        / "FS-2.4.1_BUSINESS_EDGE_CLASSIFICATION.md"
    )

    require(fs_241)

    TEST.parent.mkdir(parents=True, exist_ok=True)
    DOC.parent.mkdir(parents=True, exist_ok=True)

    if TEST.exists():
        fail(
            "Gate already exists: "
            + str(TEST.relative_to(ROOT))
        )

    if DOC.exists():
        fail(
            "Documentation already exists: "
            + str(DOC.relative_to(ROOT))
        )

    DOC.write_text(REPORT, encoding="utf-8")
    TEST.write_text(JAVA, encoding="utf-8")

    print("FS-2.4.2 module boundary gate installed.")
    print()
    print("Created:")
    print(" -", DOC.relative_to(ROOT))
    print(" -", TEST.relative_to(ROOT))
    print()
    print("Policy:")
    print(" - current 4 business edges explicitly frozen")
    print(" - port.in and port.input both accepted")
    print(" - reviewed Security contracts explicitly allowed")
    print(" - infrastructure/repository/JPA/output-port imports forbidden")
    print(" - Java cycles forbidden")
    print(" - Maven cycles forbidden")
    print(" - unused Maven business dependencies forbidden")
    print(" - new business edges require explicit review")
    print()
    print("Run from backend:")
    print(
        "  mvn -pl bootstrap -am "
        "-Dtest=BusinessModuleBoundaryArchitectureTest test"
    )
    print()
    print("Then:")
    print("  mvn verify")

if __name__ == "__main__":
    main()
